--   fish[id]  = { n,sk,dif,sz,wt,rank,leg,lf,item,mh,rar,hp,mp,mo,qo,ct,ki }
--   baits[id] = { n,t(0 bait/1 lure/2 special),mh,lo,fl }
--   aff[baitid] = { [fishid]=power 1..3 }   (no entry = cannot hook)
--   rods[id]  = the fishing_rod row (verdict math)
--   pools[zone][area] = sorted fishid list; zones[zone]={n,dif}; areaNames[zone][area]=name
--   mobs[zone] = { {n,a,b,ab,nm,lv} } (b=required bait id, 0 = any)
--   gearBonus[itemid] = { n,sl,lv, fish/penguin/albatross/pelican }
--   rules  = the static-progression hook limit and skill-up rules
--   points = Fishing points a landed fish pays, by its skill level
--   shop   = Fennella's shelf (Port Windurst), priced in Fishing points
